// ─── File: src/main/java/com/bank/core/NativeCodec.java ───
package com.bank.core;

import java.io.*;

// Native Java serialization: JAVA-ONLY, acceptable for trusted internal caches.
public class NativeCodec {
    public byte[] encode(Account a) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(buffer)) {
            oos.writeObject(a);
        }
        return buffer.toByteArray();
    }
    public Account decode(byte[] bytes) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois =
                 new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            // In production with untrusted data, set an ObjectInputFilter allowlist.
            return (Account) ois.readObject();
        }
    }
}
```

