// ─── File: src/main/java/com/bank/core/JsonCodec.java ───
package com.bank.core;

// Cross-language payload for inter-service communication. Real code uses Jackson.
public class JsonCodec {
    public String encode(Account a) {
        return "{"
             + "\"accountId\":\"" + a.getAccountId() + "\","
             + "\"holderName\":\"" + a.getHolderName() + "\","
             + "\"balance\":\"" + a.getBalance().toPlainString() + "\""
             + "}";
    }
    // Any language (Python, Go, Node) can parse this same text — that is the point.
    public int byteSize(String json) {
        return json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
    }
}
```

