// ─── File: src/main/java/com/bank/core/CodecDemo.java ───
package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class CodecDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));

        // Internal Java-only cache: native serialization round-trip.
        NativeCodec nativeCodec = new NativeCodec();
        byte[] bytes = nativeCodec.encode(rajesh);
        Account back = nativeCodec.decode(bytes);
        log.info(() -> "Native round-trip OK: " + back.getAccountId()
                        + " (" + bytes.length + " bytes, JAVA-ONLY)");

        // Inter-service: JSON payload any language can read.
        JsonCodec json = new JsonCodec();
        String payload = json.encode(rajesh);
        log.info(() -> "JSON payload (cross-language, "
                        + json.byteSize(payload) + " bytes) = " + payload);
    }
}
